/**
 * Day 8 — Greedy Algorithm. Original statements + reference solutions for the
 * in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 */

const MEETING_DENOMS = [2000, 500, 200, 100, 50, 20, 10, 5, 2, 1];

export default {
  section: 'Day 8: Greedy Algorithm',
  problems: [
    {
      slug: 'n-meetings-in-one-room',
      title: 'N Meetings in One Room',
      difficulty: 'Easy',
      topic: 'Greedy',
      description: `A room can host one meeting at a time. You are given \`N\` meetings with their start and end times. A meeting that ends at time \`t\` may be followed by another that starts at time \`t\` (back-to-back is allowed).

Find the maximum number of meetings that can be held in the room.

Input format: first line \`N\`, second line the \`N\` start times, third line the \`N\` end times.

Print the maximum number of meetings.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n1 <= start[i] < end[i] <= 10^9',
      inputs: [
        '6\n1 3 0 5 8 5\n2 4 6 7 9 9',
        '1\n1\n2',
        '3\n10 11 12\n11 12 13',
        '4\n1 2 3 4\n2 3 4 5',
        '5\n0 1 2 3 4\n10 2 3 4 5',
        '7\n2 1 3 0 5 8 5\n4 6 7 5 9 9 10',
        '4\n1 1 1 1\n2 2 2 2',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const N = Number(lines[0]);
        const starts = lines[1].split(/\s+/).map(Number);
        const ends = lines[2].split(/\s+/).map(Number);
        const meetings = [];
        for (let i = 0; i < N; i++) meetings.push([starts[i], ends[i], i]);
        meetings.sort((a, b) => a[1] - b[1] || a[0] - b[0] || a[2] - b[2]);
        let count = 0, lastEnd = -Infinity;
        for (const [s, e] of meetings) {
          if (s >= lastEnd) { count++; lastEnd = e; }
        }
        return String(count);
      },
    },
    {
      slug: 'minimum-platforms',
      title: 'Minimum Platforms Required',
      difficulty: 'Medium',
      topic: 'Greedy',
      description: `A railway station has trains arriving and departing. A train needs a platform from its arrival time until its departure time. If one train departs at the exact moment another arrives, the departing train frees its platform first.

Find the minimum number of platforms so that no train ever waits.

Input format: first line \`N\`, second line the \`N\` arrival times, third line the \`N\` departure times.

Print the minimum number of platforms needed.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n0 <= arrival[i] < departure[i] <= 10^9\nAll times are integers',
      inputs: [
        '6\n900 940 950 1100 1500 1800\n910 1200 1120 1130 1900 2000',
        '1\n100\n200',
        '3\n100 100 100\n101 101 101',
        '4\n100 200 300 400\n100 200 300 400',
        '5\n0 1 2 3 4\n10 5 6 7 8',
        '7\n910 940 950 1100 1150 1200 1300\n1120 1200 1150 1130 1300 1230 1400',
        '3\n10 11 12\n13 12 14',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const N = Number(lines[0]);
        const arrivals = lines[1].split(/\s+/).map(Number).slice(0, N).sort((a, b) => a - b);
        const departures = lines[2].split(/\s+/).map(Number).slice(0, N).sort((a, b) => a - b);
        let i = 0, j = 0, cur = 0, best = 0;
        while (i < N && j < N) {
          if (arrivals[i] < departures[j]) {
            cur++;
            best = Math.max(best, cur);
            i++;
          } else {
            cur--;
            j++;
          }
        }
        return String(best);
      },
    },
    {
      slug: 'job-sequencing',
      title: 'Job Sequencing with Deadlines',
      difficulty: 'Hard',
      topic: 'Greedy',
      description: `You have \`N\` jobs. Each job takes exactly **one unit** of time, has a deadline, and earns a profit if completed by its deadline. You may schedule at most one job per unit of time, and time slots are numbered 1, 2, 3, ...

Find a schedule that maximizes total profit and print that maximum profit.

Input format: first line \`N\`, then \`N\` lines each containing \`deadline profit\`.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n1 <= deadline <= N\n1 <= profit <= 10^5',
      inputs: [
        '4\n4 20\n1 10\n1 40\n1 30',
        '1\n1 50',
        '5\n2 100\n1 19\n1 27\n1 25\n1 15',
        '3\n3 40\n3 30\n3 20',
        '6\n3 40\n1 10\n1 10\n2 75\n2 60\n2 50',
        '4\n4 5\n3 6\n2 7\n1 8',
        '5\n5 1\n4 2\n3 3\n2 4\n1 5',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const N = Number(lines[0]);
        const jobs = [];
        for (let i = 1; i <= N; i++) {
          const [deadline, profit] = lines[i].split(/\s+/).map(Number);
          jobs.push({ deadline, profit });
        }
        jobs.sort((a, b) => b.profit - a.profit);
        const slot = new Array(N + 1).fill(false);
        let total = 0;
        for (const job of jobs) {
          for (let t = job.deadline; t >= 1; t--) {
            if (!slot[t]) { slot[t] = true; total += job.profit; break; }
          }
        }
        return String(total);
      },
    },
    {
      slug: 'fractional-knapsack',
      title: 'Fractional Knapsack',
      difficulty: 'Medium',
      topic: 'Greedy',
      description: `A knapsack can carry at most \`W\` units of weight. There are \`N\` items; item \`i\` has value \`v\` and weight \`w\`. You may take a whole item or any fraction of it, gaining that fraction of its value.

Maximize the total value carried and print it with **exactly 2 decimal places**.

Input format: first line has \`N W\`, then \`N\` lines each containing \`value weight\`.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^4\n1 <= W <= 1000\n1 <= value, weight <= 1000',
      inputs: [
        '3 50\n60 20\n100 50\n120 30',
        '1 10\n100 20',
        '2 10\n10 10\n5 10',
        '3 10\n5 5\n10 10\n15 15',
        '4 15\n10 5\n20 10\n30 4\n40 6',
        '3 7\n14 7\n28 14\n21 11',
        '5 100\n100 10\n200 20\n300 30\n400 40\n500 50',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const [N, W] = lines[0].split(/\s+/).map(Number);
        const items = [];
        for (let i = 1; i <= N; i++) {
          const [value, weight] = lines[i].split(/\s+/).map(Number);
          items.push({ value, weight, ratio: value / weight });
        }
        items.sort((a, b) => b.ratio - a.ratio);
        let capacity = W, total = 0;
        for (const item of items) {
          if (capacity <= 0) break;
          const taken = Math.min(item.weight, capacity);
          capacity -= taken;
          total += item.value * (taken / item.weight);
        }
        return total.toFixed(2);
      },
    },
    {
      slug: 'minimum-coins',
      title: 'Greedy: Minimum Number of Coins',
      difficulty: 'Easy',
      topic: 'Greedy',
      description: `Indian currency comes in these coin/bill denominations:

\`1, 2, 5, 10, 20, 50, 100, 200, 500, 2000\`

Given an amount \`S\`, find the **minimum number of coins** needed to make exactly that amount (you have unlimited supply of each denomination).

Input format: one line containing \`S\`.

Print the minimum number of coins.

{{EXAMPLES}}`,
      constraints: '1 <= S <= 10^4',
      inputs: ['49', '1', '93', '100', '2000', '7', '1234'],
      solve(input) {
        let s = Number(input.trim());
        let count = 0;
        for (const coin of MEETING_DENOMS) {
          count += Math.floor(s / coin);
          s %= coin;
        }
        return String(count);
      },
    },
    {
      slug: 'activity-selection-indices',
      title: 'Activity Selection (print chosen activities)',
      difficulty: 'Medium',
      topic: 'Greedy',
      description: `There are \`N\` activities with start and end times; only one can run at a time and an activity may start exactly when another ends.

Choose activities with this deterministic greedy rule:
1. pick the available activity with the **smallest end time**;
2. break ties by the **smallest start time**;
3. break remaining ties by the **earliest position in the input**.

Print the **1-based input positions** of the chosen activities, in the order they would be executed, separated by single spaces.

Input format: first line \`N\`, then \`N\` lines each containing \`start end\`.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n0 <= start < end <= 10^9',
      inputs: [
        '6\n1 2\n3 4\n0 6\n5 7\n8 9\n5 9',
        '1\n1 2',
        '3\n1 3\n2 4\n4 6',
        '4\n1 1\n2 2\n3 3\n4 4',
        '5\n10 20\n10 15\n15 25\n20 30\n25 35',
        '4\n0 10\n1 2\n3 4\n5 6',
        '7\n5 6\n5 6\n7 8\n1 2\n1 2\n9 10\n9 10',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const N = Number(lines[0]);
        const activities = [];
        for (let i = 0; i < N; i++) {
          const [start, end] = lines[i + 1].split(/\s+/).map(Number);
          activities.push({ start, end, idx: i + 1 });
        }
        activities.sort((a, b) => a.end - b.end || a.start - b.start || a.idx - b.idx);
        const chosen = [];
        let lastEnd = -Infinity;
        for (const act of activities) {
          if (act.start >= lastEnd) { chosen.push(act.idx); lastEnd = act.end; }
        }
        return chosen.join(' ');
      },
    },
  ],
};
